/* Free, local course chatbot. Uses curated answers and extractive retrieval; no LLM or network calls. */
(function(){
'use strict';
const all=window.COURSE.modules.flatMap(m=>m.lessons),byId=new Map(all.map(l=>[l.id,l]));
const plain=html=>{const t=document.createElement('div');t.innerHTML=html;return(t.textContent||'').replace(/\s+/g,' ').trim();};
const stop=new Set('a an and are as at be can could do does for from have how i in is it me my of on or please should tell that the their this to want what when where which who why will with would you your about need help get'.split(' '));
const tokens=s=>s.toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>2&&!stop.has(w));
const index=all.map(l=>{const el=document.createElement('div');el.innerHTML=l.html;return{lesson:l,title:tokens(l.title),words:tokens(plain(l.html)),paragraphs:[...el.querySelectorAll('p,li')].filter(p=>!p.classList.contains('source-note')).map(p=>p.textContent.trim()).filter(p=>p.length>45)};});
const entries=[
{keys:['start','begin','first step'],answer:'Start by exploring your interests, strengths and possible education routes. Then compare programmes for academic, personal and financial fit. The year-group pathway gives EY, S4, S5 and S6 students a suggested sequence.',ids:['foundation-identity','explore-pathways','3'],route:['pathways','Choose my year-group pathway']},
{keys:['essay','personal statement','write essay'],answer:'Begin with a real experience and what it reveals about you. Brainstorm before choosing a structure, draft in your own voice, and show specific actions and reflection. Revise against the actual prompt and word limit. I can point you to examples and activities; the application writing should remain your own.',ids:['9','29','30','41']},
{keys:['scholarship','scholarships','financial aid','funding','fafsa'],answer:'Check whether each award accepts applicants with your citizenship, qualifications and intended programme. Record what it covers, the deadline, separate application requirements and renewal conditions. Compare the full cost with confirmed support. Most foreign citizens are not eligible for US federal aid, though eligible noncitizen categories exist; use the linked funding lessons and official sources to check your situation.',ids:['14','16','15']},
{keys:['budget','cost','afford','money','pay','tuition'],answer:'List tuition, housing, meals, transport, insurance and other required costs. Subtract confirmed grants or scholarships to find the remaining cost, then compare it with the resources you can actually provide. Keep hoped-for funding separate. The course budget examples are fictional, not current price estimates.',ids:['15','career-budget','19']},
{keys:['deadline','deadlines','timeline','calendar','schedule'],answer:'Make a tracker for each institution: application deadline and time zone, programme deadline, funding deadline, required records, tests and recommendations. Work backwards and leave time for review. I do not check live deadlines; confirm dates on the institution’s current official page.',ids:['5','6','42']},
{keys:['recommendation','recommendations','reference','recommender','brag'],answer:'Ask someone who knows your work and can give specific examples. Share the opportunity, deadline, submission instructions and an accurate summary of your experiences. Ask early, follow the required number and type of references, and thank the recommender. Do not write or submit a letter pretending to be them.',ids:['13','career-portfolio']},
{keys:['sat','act','duolingo','ielts','toefl','test','testing','tests'],answer:'Check the current testing requirements for each programme and your qualifications before booking a test. Distinguish admissions tests from English-language evidence. Use a practice result to plan focused study, then check fees, available dates and score-reporting deadlines with the official provider.',ids:['8','foundation-goals']},
{keys:['early decision','ed','early action','ea','binding'],answer:'Early Decision involves a commitment to attend under the agreement if admitted; Early Action is generally non-binding, with restrictions possible under some plans. Review fit, affordability and the exact agreement with your counsellor before applying. If an aid offer is unaffordable, discuss the review or release process directly with the institution.',ids:['6','14']},
{keys:['ucas','uk','united kingdom'],answer:'Use the UCAS lesson to plan the three personal-statement responses used from 2026 entry onwards. Connect your motivation, academic preparation and relevant experiences to the course. Check the current character limits, deadlines and course requirements directly with UCAS and the university.',ids:['11','40','6']},
{keys:['common app','commonapp','application platform'],answer:'Prepare your records, education details, activities and writing before entering them. Check each college’s requirements, preview the application, and verify submission and portal updates. Different colleges can require different questions and documents even when using the same platform.',ids:['39','17','18']},
{keys:['cv','resume','activities','activity','extracurricular','awards'],answer:'Describe your own responsibilities and contribution with clear action verbs. Use honest dates, hours and results; include family or community responsibilities when relevant. Select the evidence that fits the opportunity rather than filling space with unsupported claims.',ids:['12','38','career-portfolio']},
{keys:['college list','shortlist','university list','choose college','best college'],answer:'Compare course content, entry requirements, learning environment, support and total cost. Keep official sources and unresolved questions in your research notes. Build a list with realistic academic and financial options; a famous name alone does not establish fit.',ids:['3','4','21']},
{keys:['career','careers','major','degree','tvet'],answer:'Start with tasks and subjects you enjoy, skills you can demonstrate and values that matter to you. Research the daily work and training of several careers, then compare suitable education routes. Informational interviews and supervised experiences can help you test your assumptions.',ids:['explore-pathways','explore-research','explore-interview']},
{keys:['internship','volunteer','holiday','job shadow'],answer:'Choose a learning goal and agree a manageable task with an appropriate supervisor. Confirm the schedule, location, costs, permissions and support contact before starting. Keep a journal of your contribution, feedback and learning; a local project can also provide useful experience.',ids:['explore-experience','explore-interview']},
{keys:['interview','introduce','communication'],answer:'Prepare a few honest examples of a challenge, contribution or learning experience. Explain the situation, task, action and result or lesson. Practise speaking clearly with a partner, listen carefully and ask for clarification when needed.',ids:['25','foundation-communication','career-interview']},
{keys:['ai','chatgpt','artificial intelligence'],answer:'Follow the school’s and application platform’s rules. When permitted, use tools to clarify ideas or ask reflection questions, then check facts yourself. Keep your experiences truthful and your writing your own. This CRC chatbot uses prepared guidance and course excerpts; it is not a generative AI service.',ids:['foundation-digital','41']},
{keys:['progress','saved','save','workbook','notes','download'],answer:'Lesson notes and progress are saved in this browser on this device. Use My application workbook to download or print your responses. They do not sync between devices or different site addresses. On shared computers, download your work before clearing course data.',ids:[],route:['workbook','Open my application workbook']},
{keys:['rejected','rejection','stress','overwhelmed','backup','transition'],answer:'Choose one manageable next action and speak with a trusted adult or counsellor about support and alternatives. A changed plan is not a judgement of your worth. You can compare other programmes, training routes or preparation opportunities and set a date to review your next steps.',ids:['19','career-transition','foundation-goals']}
];
let lastIds=[],lastQuestion='';
function search(query){const q=[...new Set(tokens(query))];if(!q.length)return[];return index.map(x=>{let matches=0,score=0;for(const w of q){const title=x.title.some(t=>t===w||t.startsWith(w));const body=x.words.includes(w);if(title||body)matches++;score+=title?6:body?1:0;}return{...x,score:score*(matches/q.length),matches};}).filter(x=>x.score>=2&&x.matches>=Math.min(q.length,2)).sort((a,b)=>b.score-a.score).slice(0,3);}
function respond(raw){const text=raw.trim().slice(0,1000),low=text.toLowerCase();
if(/^(hi|hello|hey|thanks|thank you)[!. ]*$/.test(low))return{answer:'Hello! Ask me about college applications, career preparation or using the CRC course. Try “How do I start my essay?” or choose a topic below.',ids:[]};
if(/(write|generate|create).*(my|personal|application).*(essay|statement)|write.*essay.*(me|submit)/.test(low))return{answer:'I can help you plan your own essay. Choose a real moment, describe what you did, and explain what changed in your thinking. Use the brainstorming and structure lessons below to begin; I do not write submission-ready essays for you.',ids:['9','29','30']};
if(/\b(example|examples|more|explain|activity|practice)\b/.test(low)&&lastIds.length&&tokens(text).length<=3){const results=lastIds.map(id=>index.find(x=>x.lesson.id===id)).filter(Boolean);const preferred=results.flatMap(x=>x.paragraphs.map(p=>({p,l:x.lesson}))).find(x=>/fictional|example/i.test(x.p));const x=preferred||{p:results[0].paragraphs[0],l:results[0].lesson};return{answer:'Here is an excerpt from the related course lesson:',ids:[x.l.id],excerpt:x.p,activity:x.l.activity};}
const ranked=entries.map(e=>({...e,n:e.keys.reduce((n,k)=>n+(new RegExp('(^|[^a-z])'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z]|$)','i').test(low)?(k==='start'||k==='begin'?0.25:k.split(' ').length):0),0)})).sort((a,b)=>b.n-a.n);
if(ranked[0].n>0){const e=ranked[0];return{answer:e.answer,ids:e.ids,route:e.route};}
const result=search(text);if(result.length)return{answer:'I found related material in the course. This excerpt may help; open the lesson for the full explanation.',ids:result.map(x=>x.lesson.id),excerpt:result[0].paragraphs.map(p=>({p,n:tokens(text).filter(w=>tokens(p).includes(w)).length})).sort((a,b)=>b.n-a.n)[0]?.p};
return{answer:'I could not find a reliable answer in this course. Try a specific topic such as essay brainstorming, scholarships, recommendations or career research. For current university requirements or advice about your own application, check the official institution website or speak with your counsellor.',ids:[],route:['resources','Open course resources']};}
window.CRCChat={respond,search};
const launcher=document.createElement('button');launcher.id='chat-launcher';launcher.type='button';launcher.textContent='Ask CRC';launcher.setAttribute('aria-controls','crc-chat');launcher.setAttribute('aria-expanded','false');
const panel=document.createElement('section');panel.id='crc-chat';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','CRC course chatbot');panel.innerHTML=`<div class="chat-head"><div><strong>CRC course chatbot</strong><span>Guidance from your course</span></div><button type="button" id="chat-close" aria-label="Close chatbot">×</button></div><p class="chat-about">Prepared answers and lesson excerpts, not generative AI. No live web search. Questions stay in this tab and are not saved.</p><div id="chat-log" role="log" aria-live="polite" aria-relevant="additions" tabindex="0"></div><div class="chat-prompts"><button type="button" data-prompt="How do I start my essay?">Essays</button><button type="button" data-prompt="How do I find scholarships?">Funding</button><button type="button" data-prompt="How do I explore careers?">Careers</button><button type="button" id="chat-current">This lesson</button></div><form id="chat-form"><label for="chat-input">Your question</label><div><input id="chat-input" type="text" maxlength="1000" autocomplete="off" placeholder="Ask about applications or careers…" required><button type="submit">Send</button></div></form><div class="chat-footer"><span>Keep passwords and private records out of chat.</span><button type="button" id="chat-clear">Clear chat</button></div>`;
document.body.append(launcher,panel);const log=panel.querySelector('#chat-log'),input=panel.querySelector('#chat-input');
function message(role,text,result){const article=document.createElement('div');article.className='chat-message '+role;const label=document.createElement('strong');label.className='chat-role';label.textContent=role==='student'?'You':'CRC';article.append(label);const p=document.createElement('p');p.textContent=text;article.append(p);if(result?.excerpt){const quote=document.createElement('blockquote');quote.textContent=result.excerpt;article.append(quote);}if(result?.activity){const activity=document.createElement('p');activity.textContent='Try this: '+result.activity;article.append(activity);}if(result?.ids?.length||result?.route){const ul=document.createElement('ul');for(const id of(result.ids||[])){const l=byId.get(id);if(!l)continue;const li=document.createElement('li'),a=document.createElement('a');a.href='#lesson/'+id;a.textContent=l.title;li.append(a);ul.append(li);}if(result.route){const li=document.createElement('li'),a=document.createElement('a');a.href='#'+result.route[0];a.textContent=result.route[1];li.append(a);ul.append(li);}article.append(ul);}log.append(article);while(log.children.length>40)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;}
function welcome(){message('bot','Hi! I can guide you to course explanations, examples and activities. What would you like help with?');}
function ask(text){if(!text.trim())return;message('student',text.trim());const result=respond(text);lastQuestion=text;lastIds=result.ids||[];message('bot',result.answer,result);input.value='';input.focus();}
function toggle(open){panel.hidden=!open;launcher.setAttribute('aria-expanded',String(open));if(open)input.focus();else launcher.focus();}
launcher.onclick=()=>toggle(panel.hidden);panel.querySelector('#chat-close').onclick=()=>toggle(false);panel.addEventListener('keydown',e=>{if(e.key==='Escape'){toggle(false);e.stopPropagation();}});panel.querySelector('#chat-form').onsubmit=e=>{e.preventDefault();ask(input.value);};panel.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));panel.querySelector('#chat-clear').onclick=()=>{log.replaceChildren();lastIds=[];lastQuestion='';welcome();input.focus();};panel.querySelector('#chat-current').onclick=()=>{const id=location.hash.startsWith('#lesson/')?location.hash.slice(8):'';const l=byId.get(id);if(!l){message('bot','Open a course lesson, then choose “This lesson” for its practice task.',{route:['home','Open course overview']});return;}lastIds=[id];message('bot','You are studying “'+l.title+'”. Here is your practical task:',{activity:l.activity,ids:[id]});};log.addEventListener('click',e=>{if(e.target.closest('a'))toggle(false);});welcome();
})();
